from primitives import call

def live_meat_position():
    loc = call(
        name="locate_robocasa365_object",
        object_name="meat",
        prompt="Locate the exact current live steak pose after the previous contact.",
        query="current meat position"
    )
    found = []
    def scan(node, path):
        if isinstance(node, dict):
            for key, value in node.items():
                pth = path + "/" + str(key).lower()
                if isinstance(value, (list, tuple)) and len(value) == 3:
                    valid = True
                    vals = []
                    for x in value:
                        if isinstance(x, bool) or not isinstance(x, (int, float)):
                            valid = False
                        else:
                            vals.append(float(x))
                    if valid and ("position" in pth or "centroid" in pth or "translation" in pth):
                        if 3.4 < vals[0] < 4.9 and -1.3 < vals[1] < 0.5 and 0.65 < vals[2] < 1.35:
                            found.append(vals)
                scan(value, pth)
        elif isinstance(node, (list, tuple)):
            for value in node:
                scan(value, path)
    if loc.ok:
        scan(loc.output, "")
    pos = None
    for item in found:
        pos = item
    if pos is None:
        pos = [4.138908863067627, -0.35863929986953735, 0.9348503351211548]
    return pos

