)

position_records = []

def collect_positions(node, path):
    if isinstance(node, dict):
        local_name = ""
        for key, value in node.items():
            if isinstance(value, str):
                local_name += " " + value.lower()
        for key, value in node.items():
            key_text = str(key).lower()
            new_path = path + "/" + key_text
            if isinstance(value, (list, tuple)) and len(value) == 3:
                vals = []
                valid = True
                for x in value:
                    if isinstance(x, bool) or not isinstance(x, (int, float)):
                        valid = False
                    else:
                        vals.append(float(x))
                if valid and ("position" in key_text or "centroid" in key_text or "translation" in key_text):
                    if 3.7 < vals[0] < 4.6 and -0.9 < vals[1] < 0.1 and 0.75 < vals[2] < 1.15:
                        score = 0
                        if "meat" in local_name or "steak" in local_name:
                            score += 10
                        if "object" in new_path:
                            score += 4
                        if "position" in key_text:
                            score += 3
                        if "eef" in new_path or "robot" in new_path or "target" in new_path:
                            score -= 8
                        position_records.append([score, vals, new_path])
            collect_positions(value, new_path)
    elif isinstance(node, (list, tuple)):
        for value in node:
            collect_positions(value, path)

